/**
 * The homepage's and the site chrome's editable copy and media.
 *
 * Transcribed from the m.on website prototype (m-on-website/index.html and
 * js/home-defaults.js): its English and Arabic text, and its German and
 * Turkish from the prototype's own translation tables (js/i18n-de.js,
 * js/i18n-tr.js), so all four languages read as the designer wrote them.
 * Generated — regenerate rather than hand-edit large parts.
 *
 * Two sections:
 *
 *   - `home`: every section of the homepage, top to bottom, including the
 *     prototype's blocks it did not make editable (before & after, the
 *     expectation cards, the gallery, the moving day, the guides).
 *   - `chrome`: the top bar, the header and its services menu, the request
 *     basket, the footer and the cookie card, shown on every public page.
 *
 * Links are site paths without the language ("/kontakt"); the page adds it.
 * Photos are files under apps/web/public/images/mon; the hero's clips are
 * the prototype's stock videos until the office uploads its own.
 *
 * Replacing the old homepage's rows (frame 357:23886) needs a forced, pruned
 * run, which drops the slots the new page no longer reads:
 *
 *     pnpm seed:home --section=home,chrome --force --prune
 */

export interface ContentSeed {
  section: string;
  slot: string;
  /**
   * "image" holds a picture's path or https URL, "video" a clip's; both are
   * the same in every locale.
   */
  kind: "text" | "textarea" | "image" | "video";
  label: string;
  sortOrder: number;
  values: { de: string; en: string; ar: string; tr: string };
}

function row(
  section: string,
  slot: string,
  kind: ContentSeed["kind"],
  label: string,
  sortOrder: number,
  values: ContentSeed["values"],
): ContentSeed {
  return { section, slot, kind, label, sortOrder, values };
}

/** A row that reads the same in every language: a path, a name, a figure. */
const same = (value: string): ContentSeed["values"] => ({ de: value, en: value, ar: value, tr: value });

